/* glow effect - start */
@property --angle {
  syntax: "<angle>";
  inherits: true;
  initial-value: 0deg;
}

selector .box-wrapper {
  background: #101820;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 0;
}

selector .box {
  width: 100px;
  height: 100px;
  margin: 3px;
  border-radius: 12px;
  background: #101820;
  position: absolute;
}

selector .box::after,
selector .box::before {
  content: "";
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: conic-gradient(
    from var(--angle),
    #e9f3ff,
    #fe5c01,
    #101820,
    #101820,
    #fe5c01,
    #e9f3ff,
    #fe5c01,
    #101820,
    #101820,
    #fe5c01,
    #e9f3ff
  );
  z-index: -1;
  transform: scale(1.02);
  animation: animate 12s linear infinite;
}

selector .box::before {
  filter: blur(5px);
}

@keyframes animate {
  to {
    --angle: 360deg;
  }
}
/* glow effect - end */

